{
  "decision": "accept",
  "icd10_code": "E11.22",
  "code_display": "Type 2 DM with diabetic CKD",
  "guideline_citations": [
    {
      "url": "https://www.cms.gov/files/document/fy-2027-icd-10-cm-coding-guidelines.pdf",
      "quote": "The classification presumes a causal relationship between the two conditions linked by these terms in the Alphabetic Index or Tabular List. These conditions should be coded as related even in the absence of provider documentation explicitly linking them, unless the documentation clearly states the conditions are unrelated or when another guideline exists that specifically requires a documented linkage between two conditions (e.g., sepsis guideline for “acute organ dysfunction that is not clearly associated with the sepsis”).",
      "source": "CMS FY 2027 ICD-10-CM Official Guidelines, Section I.A.15"
    }
  ],
  "rationale": "The chart contains multiple explicit statements of Type 2 diabetes mellitus (e.g., '68-year-old Hispanic female with Type 2 diabetes presents for follow-up', 'Type 2 diabetes mellitus – UNCONTROLLED with hyperglycemia'), a documented chronic kidney disease diagnosis ('Chronic kidney disease, Stage 3 – eGFR 48, declining'), and a direct linkage phrase 'Likely diabetic nephropathy.' Per ICD-10-CM guideline I.A.15, a causal relationship between diabetes and CKD is presumed when the conditions are linked in the classification; the provider's 'likely diabetic nephropathy' further affirms the diabetic etiology. No negation, family history, screening, hypothetical, or resolved language contradicts the combination. The evidence satisfies the criteria for E11.22 without reliance on medication lists alone.",
  "physician_query_needed": false
}
